export const RAW_WORD_POOL: Word[] = (POOL_PART_0 as Word[]).concat(POOL_PART_1, POOL_PART_2, POOL_PART_3, POOL_PART_4, POOL_PART_5, POOL_PART_6)

export const WORDS: Word[] = buildActiveWords(RAW_WORD_POOL, LEXICON_CONFIG)

const WORD_MAP = new Map<string, Word>(WORDS.map((w) => [w.id, w]))

export function getWord(id: string): Word | undefined {
  return WORD_MAP.get(id)
}

/** Public URL for a text-free poster, honoring the Vite base path. */
export function illustrationUrl(word: Word): string | null {
  if (!word.illustration) return null
  return import.meta.env.BASE_URL + word.illustration.replace(/^\//, "")
}
